package dev.aivillages.core.kernel.production.planning;

import java.util.*;
import java.util.stream.*;
import org.junit.jupiter.api.*;
import dev.aivillages.core.kernel.*;
import dev.aivillages.core.kernel.production.*;
import static dev.aivillages.core.kernel.Contracts.*;
import static dev.aivillages.core.kernel.production.planning.PlanningModel.*;
import static dev.aivillages.core.kernel.production.planning.PlannerFixtures.*;
import static org.junit.jupiter.api.Assertions.*;

/** Logic/port fixtures only. These tests provide no native gameplay, activity or recovery evidence. */
final class ProductionPlannerTest {
    final StaticProductionPlanner planner=new StaticProductionPlanner();final PlanningCoordinator coordinator=new PlanningCoordinator();
    @Test void threeLogsSupportTableSticksAxeWithExactResidualsAndNoPhysicalMutation(){var f=new PlannerFixtures().logs(3);var before=List.copyOf(f.stock);var s=f.snapshot();var a=planner.analyse(s);assertEquals(Feasibility.FEASIBLE,a.feasibility(),a.reason());assertEquals(7,a.plan().actions().size());
        assertEquals(3,a.residual().get(PLANK));assertEquals(2,a.residual().get(STICK));assertFalse(a.residual().containsKey(AXE));assertEquals(before,f.stock);assertEquals(1,s.goal().demand());assertEquals(0,s.confirmedCredit());
        assertEquals(12,a.plan().actions().stream().filter(x->x.result().equals(PLANK)).mapToLong(Action::yield).sum());assertEquals(1,a.plan().actions().stream().filter(x->x.kind()==Kind.PLACE_TABLE).count());
        var decision=coordinator.next(s,null,Memory.empty());assertEquals(DecisionKind.BLOCKED,decision.kind());assertNotNull(decision.neededChoice());var selected=f.withChoice(decision);assertEquals(DecisionKind.PROPOSE,selected.kind(),selected.blocker());assertEquals(0,selected.proposal().quantities().goalAllocationUpperBound());assertEquals(Predicate.CURRENT_MATERIALS,selected.proposal().checkpoint().predicate());assertEquals(0,selected.proposal().requestedAllowance().get(Counter.MODEL_CALLS));
        System.out.println("B05_PURE_AXE inputLogs=3 producedPlanks=12 residualPlanks=3 residualSticks=2 nativeGameplay=false");}
    @TestFactory Stream<DynamicTest> rootQuantityAndSurplusBoundaries(){return IntStream.of(1,3,4,5,7,16,63,64).mapToObj(q->DynamicTest.dynamicTest("MAKE q="+q+" retains exact demand and bounded physical surplus",()->{
        var f=new PlannerFixtures().goal(Mode.MAKE_NEW,PLANK,q).logs((q+3)/4);var original=f.snapshot().goal();var request=coordinator.next(f.snapshot(),null,Memory.empty());assertNotNull(request.neededChoice(),request.blocker());var result=f.withChoice(request);assertEquals(DecisionKind.PROPOSE,result.kind(),result.blocker());var p=result.proposal();assertEquals(q,p.quantities().requestedDemand());assertEquals(q,p.quantities().nativeDelivery());assertEquals(q,p.quantities().goalAllocationUpperBound());assertEquals((q+3)/4*4,p.quantities().newPhysicalOutput());assertEquals((4-q%4)%4,p.quantities().actorSurplus());assertEquals(original,f.snapshot().goal());assertEquals(p.nativeChoice().choice().digest(),RecipeChoice.fromCanonical(p.nativeChoice().choice().canonical()).digest());}));}
    @Test void sevenLogTransportRespectsCarryingLimitAndFourAcceptedDeliveriesLeaveThree(){var f=new PlannerFixtures().goal(Mode.ACQUIRE_NEW,LOG,7).logSource(7);f.carry=4;var first=coordinator.next(f.snapshot(),null,Memory.empty());assertEquals(DecisionKind.PROPOSE,first.kind());assertEquals(4,first.proposal().quantities().requestedDemand());assertEquals(4,((IntValue)first.proposal().requestedInvocation().arguments().get("amount")).value());
        var plan=first.analysis().plan();f.settle(plan,0,4,4);f.acquisition.set(0,new Acquisition("fixture:tree",f.area,LOG,3,Availability.PRESENT,true,true,f.acquisition.getFirst().method(),new Cost(2,3,10)));var next=coordinator.next(f.snapshot(),plan,first.memory());assertEquals(DecisionKind.PROPOSE,next.kind(),next.blocker());assertEquals(3,next.proposal().quantities().requestedDemand());assertEquals(7,next.analysis().plan().goal().demand());assertEquals(first.proposal().method().artifactHash(),next.proposal().method().artifactHash());assertEquals(0,next.proposal().requestedAllowance().get(Counter.MODEL_CALLS));}
    @Test void oldFinalStockCannotSatisfyMakeButSupplyAtDestinationNeedsNoPointlessTransfer(){var make=new PlannerFixtures().goal(Mode.MAKE_NEW,PLANK,3);make.stock.add(make.stock("old-final",1,PLANK,50));assertEquals(Feasibility.INFEASIBLE,planner.analyse(make.snapshot()).feasibility());make.logs(1);assertEquals(Feasibility.FEASIBLE,planner.analyse(make.snapshot()).feasibility());
        var supply=new PlannerFixtures().goal(Mode.SUPPLY,PLANK,3);supply.destination=supply.source;supply.stock.add(supply.stock("available-final",1,PLANK,3));var result=coordinator.next(supply.snapshot(),null,Memory.empty());assertEquals(DecisionKind.PROPOSE,result.kind());assertEquals(Kind.ALLOCATE_CURRENT,result.proposal().kind());assertEquals(0,result.proposal().quantities().newPhysicalOutput());assertEquals(0,result.proposal().quantities().nativeDelivery());assertEquals(3,result.proposal().quantities().goalAllocationUpperBound());assertEquals(0,result.proposal().requestedAllowance().get(Counter.EFFECTS));}
    @Test void impossibleAndUnknownEvidenceRemainDifferentAndNeverProduceAnEffectProposal(){var empty=new PlannerFixtures();assertEquals(Feasibility.INFEASIBLE,planner.analyse(empty.snapshot()).feasibility());var unknown=new PlannerFixtures();unknown.stock.add(new Stock("fixture:unknown",new Location(unknown.source,null,0),LOG,0,0,0,null,List.of(),Eligibility.NONE,Availability.UNKNOWN,true,false,0,1));var result=coordinator.next(unknown.snapshot(),null,Memory.empty());assertEquals(Feasibility.UNKNOWN,result.analysis().feasibility());assertNull(result.proposal());
        var noTable=new PlannerFixtures().logs(3);noTable.provision=false;assertEquals(Feasibility.INFEASIBLE,planner.analyse(noTable.snapshot()).feasibility());}
    @Test void scarceOakIsPreservedAcrossStickAndTableInputs(){var f=new PlannerFixtures();f.stock.add(f.stock("scarce-oak",0,PLANK,4));f.stock.add(f.stock("birch",1,BIRCH,5));var old=f.recipes.get(1);f.recipes.set(1,new RecipeProfile(old.recipe(),old.capability(),List.of(List.of(PLANK),List.of(PLANK)),old.result(),old.semanticFingerprint(),old.method(),old.allowance()));
        var result=planner.analyse(f.snapshot());assertEquals(Feasibility.FEASIBLE,result.feasibility(),result.reason());long oak=result.plan().actions().stream().mapToLong(x->x.inputs().getOrDefault(PLANK,0L)).sum();assertEquals(4,oak);assertEquals(5,result.plan().actions().stream().mapToLong(x->x.inputs().getOrDefault(BIRCH,0L)).sum());var table=result.plan().actions().stream().filter(x->x.recipe().equals(CraftingTableProduction.RECIPE)).findFirst().orElseThrow();assertTrue(table.inputs().getOrDefault(PLANK,0L)<=2,"Locally legal all-oak table would destroy the whole goal");}
    @Test void removedCheckpointMaterialsAndRemovedTableInvalidateOnlyCurrentAvailability(){var f=new PlannerFixtures().logs(3);var plan=planner.analyse(f.snapshot()).plan();int planks=0;while(planks<plan.actions().size() && plan.actions().get(planks).recipe().equals(OakPlankProduction.RECIPE))planks++;assertTrue(planks>0);f.settle(plan,0,planks,0);f.stock.clear();var missing=planner.revalidate(f.snapshot(),plan);assertEquals(Feasibility.UNKNOWN,missing.feasibility());assertNull(coordinator.next(f.snapshot(),plan,Memory.empty()).proposal());
        var table=new PlannerFixtures().existingTable();table.stock.add(table.stock("planks",0,PLANK,3));table.stock.add(table.stock("sticks",1,STICK,2));var ready=planner.analyse(table.snapshot()).plan();table.facility=new Facility(table.tableSite,Availability.ABSENT,true,true,"",true,2,table.facility.placement(),table.facility.placementAllowance());assertEquals(Feasibility.UNKNOWN,planner.revalidate(table.snapshot(),ready).feasibility());}
    @Test void pinnedMethodsContinueOfflineWithNoRegenerationAndNewMissingMethodStaysBlocked(){var f=new PlannerFixtures().goal(Mode.MAKE_NEW,PLANK,3).logs(1);var request=coordinator.next(f.snapshot(),null,Memory.empty());var proposed=f.withChoice(request);var plan=proposed.analysis().plan();String digest=plan.digest();assertFalse(f.online);var offline=coordinator.next(f.snapshot(),plan,Memory.empty());assertEquals(DecisionKind.PROPOSE,offline.kind());assertEquals(proposed.proposal().method(),offline.proposal().method());assertEquals(digest,plan.digest());
        var p=f.recipes.getFirst();f.recipes.set(0,new RecipeProfile(p.recipe(),p.capability(),p.cells(),p.result(),p.semanticFingerprint(),null,p.allowance()));assertEquals(Feasibility.UNKNOWN,planner.analyse(f.snapshot()).feasibility());assertNull(coordinator.next(f.snapshot(),plan,Memory.empty()).proposal());}
    @Test void unchangedSignaturesBackOffAndStopAcrossUnrelatedAuthoritativeRevisions(){var f=new PlannerFixtures().goal(Mode.ACQUIRE_NEW,LOG,7).logSource(7);var first=coordinator.next(f.snapshot(),null,Memory.empty());var memory=first.memory();for(int i=0;i<5;i++){f.revision++;var waiting=coordinator.next(f.snapshot(),first.analysis().plan(),memory);assertNull(waiting.proposal());assertEquals(DecisionKind.WAIT,waiting.kind());memory=waiting.memory();f.now+=5000;}assertEquals(4,memory.unchangedChecks());assertEquals(Long.MAX_VALUE,memory.nextCheckMillis());f.worldRevision++;var resumed=coordinator.next(f.snapshot(),first.analysis().plan(),memory);assertEquals(DecisionKind.PROPOSE,resumed.kind(),resumed.blocker());}
    @Test void cumulativeUsageAndOriginalDeadlineCannotBeReplenished(){var f=new PlannerFixtures().goal(Mode.ACQUIRE_NEW,LOG,1).logSource(1);var used=new EnumMap<Counter,Long>(Counter.class);used.putAll(zeroCounts());used.put(Counter.TRAVEL,10L);f.budget=new Budget(f.budget.original(),used,f.budget.absoluteDeadlineMillis());var first=coordinator.next(f.snapshot(),null,Memory.empty());f.budget=new Budget(f.budget.original(),zeroCounts(),f.budget.absoluteDeadlineMillis());assertEquals("CUMULATIVE_USAGE_REGRESSED",coordinator.next(f.snapshot(),first.analysis().plan(),first.memory()).blocker());
        f.budget=new Budget(f.budget.original(),used,200000);assertEquals("ORIGINAL_BUDGET_OR_DEADLINE_CHANGED",coordinator.next(f.snapshot(),first.analysis().plan(),first.memory()).blocker());f.now=200000;assertEquals("ORIGINAL_DEADLINE_EXPIRED",coordinator.next(f.snapshot(),null,Memory.empty()).blocker());}
    @Test void wholeGoalBudgetAndKnownCarryingLimitsBlockBeforeAnyConsumption(){var f=new PlannerFixtures().logs(3);f.budget=budget(100,2,1000,1,1,1,100000);assertEquals(Feasibility.INFEASIBLE,planner.analyse(f.snapshot()).feasibility());assertNull(coordinator.next(f.snapshot(),null,Memory.empty()).proposal());var carry=new PlannerFixtures().logs(3);carry.carry=4;assertEquals(Feasibility.INFEASIBLE,planner.analyse(carry.snapshot()).feasibility());}
    @Test void unsettledOwnerCancellationExecutorAndDestinationChangesRefuse(){var f=new PlannerFixtures().goal(Mode.ACQUIRE_NEW,LOG,1).logSource(1);f.owner=new Owner(f.ownerId,f.actor,0,true,true,false,false);assertEquals("ORIGINAL_OWNER_NOT_SETTLED",coordinator.next(f.snapshot(),null,Memory.empty()).blocker());f.owner=new Owner(f.ownerId,f.actor,0,true,false,true,false);assertEquals("CANCELLATION_REQUESTED",coordinator.next(f.snapshot(),null,Memory.empty()).blocker());
        f.owner=new Owner(f.ownerId,new ActorRef(id("replacement"),id("replacement-entity"),DIM),1,true,false,false,false);assertEquals("EXECUTOR_CHANGE_NOT_AUTHORIZED",coordinator.next(f.snapshot(),null,Memory.empty()).blocker());f.owner=new Owner(f.ownerId,f.actor,0,true,false,false,false);f.destination=new ContainerRef(DIM,100,64,0);assertEquals("DESTINATION_CHANGE_NOT_AUTHORIZED",coordinator.next(f.snapshot(),null,Memory.empty()).blocker());}
    @Test void noEffectSettlementDoesNotCompleteAPlannedAction(){var f=new PlannerFixtures().goal(Mode.ACQUIRE_NEW,LOG,1).logSource(1);var p=planner.analyse(f.snapshot()).plan();f.progress.add(new SettledProgress(f.root,p.actions().getFirst().token(0),"fixture:step",id("attempt-no-effect"),"fixture:effect",List.of(),List.of("fixture:no-effect-metadata"),SettlementKind.NO_EFFECT,1,0,0));assertTrue(f.snapshot().settledActionTokens().isEmpty());assertEquals(Feasibility.FEASIBLE,planner.revalidate(f.snapshot(),p).feasibility());}
    @Test void anotherRootsOutputAndADeadActorsCustodyCannotBecomeCurrentRootCredit(){var f=new PlannerFixtures().goal(Mode.MAKE_NEW,PLANK,3);f.stock.add(new Stock("fixture:other-root",new Location(f.source,null,0),PLANK,3,3,3,id("another-root"),List.of("fixture:another-root-receipt"),Eligibility.ROOT_PRODUCED,Availability.PRESENT,true,true,0,1));assertEquals(Feasibility.INFEASIBLE,planner.analyse(f.snapshot()).feasibility());var dead=new ActorRef(id("dead"),id("dead-entity"),DIM);f.stock.clear();f.stock.add(new Stock("fixture:dead-custody",new Location(null,dead,0),PLANK,3,3,3,f.root,List.of("fixture:old-custody"),Eligibility.ROOT_PRODUCED,Availability.PRESENT,true,true,0,1));assertEquals(Feasibility.INFEASIBLE,planner.analyse(f.snapshot()).feasibility());}
    @Test void oldVersionOneMethodsKeepTheirPinnedMaterialSemanticsAndHash(){var f=new PlannerFixtures().goal(Mode.MAKE_NEW,PLANK,3).logs(1);var p=f.recipes.getFirst();var legacy=new RecipeProfile(p.recipe(),OakPlankProduction.ID,p.cells(),p.result(),p.semanticFingerprint(),new MethodPin(OakPlankProduction.ID,p.method().artifactHash(),p.semanticFingerprint(),true),p.allowance());f.recipes.set(0,legacy);var result=coordinator.next(f.snapshot(),null,Memory.empty());assertEquals(DecisionKind.PROPOSE,result.kind(),result.blocker());assertNull(result.proposal().nativeChoice());assertEquals(OakPlankProduction.ID,result.proposal().requestedInvocation().capability());assertEquals(legacy.method().artifactHash(),result.proposal().method().artifactHash());assertEquals(1,result.proposal().bindings().getFirst().units());assertThrows(IllegalArgumentException.class,()->new RecipeProfile(legacy.recipe(),legacy.capability(),List.of(List.of(item("oak_wood"))),legacy.result(),legacy.semanticFingerprint(),legacy.method(),legacy.allowance()));}
}
